import { createClient } from "@supabase/supabase-js";

const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY,
);

export { supabase };

export async function entrar(email, senha) {
  const { data, error } = await supabase.auth.signInWithPassword({
    email,
    password: senha,
  });
  if (error) throw new Error("E-mail ou senha inválidos");
  return data.session;
}

export function validarPreferencias(selecionadas) {
  const obrigatorias = selecionadas.filter((d) => d.tipo === "obrigatoria");
  const optativas = selecionadas.filter((d) => d.tipo === "optativa");
  if (obrigatorias.length !== 4) {
    throw new Error("Escolha exatamente 4 disciplinas obrigatórias");
  }
  if (optativas.length > 2) {
    throw new Error("Escolha no máximo 2 disciplinas optativas");
  }
  return selecionadas;
}

export function statusDisciplina(total) {
  if (total >= 60) return "lotada";
  if (total < 3) return "candidata-a-cancelamento";
  return "ativa";
}
